import React, { useEffect, useState } from 'react';
import { getAllMovies } from '../api/movieApi';
import 'bootstrap/dist/css/bootstrap.min.css';

const MovieList = () => {
  const [movies, setMovies] = useState([]);

  const fetchMovies = async () => {
    try {
      const res = await getAllMovies();
      setMovies(res.data);
    } catch (error) {
      console.error("Error al cargar las películas:", error);
    }
  };

  useEffect(() => {
    fetchMovies();
  }, []);

  return (
    <div className="container-fluid mt-4">
      <div className="row">
        {/* Contenido principal */}
        <div className="col-md-9">
          <h2 className="text-center mb-4">Lista de Películas</h2>
          <div className="table-responsive shadow rounded">
            <table className="table table-striped table-hover table-bordered align-middle">
              <thead className="table-dark">
                <tr>
                  <th>Nombre</th>
                  <th>Estado</th>
                </tr>
              </thead>
              <tbody>
                {movies.length > 0 ? (
                  movies.map((movie) => (
                    <tr key={movie.id}>
                      <td>{movie.name}</td>
                      <td>
                        <span
                          className={`badge ${
                            movie.status === 'A' ? 'bg-success' : 'bg-secondary'
                          }`}
                        >
                          {movie.status === 'A' ? 'Activo' : 'Inactivo'}
                        </span>
                      </td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan="2" className="text-center">
                      No hay películas disponibles
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>

        {/* Sidebar derecho */}
        <div className="col-md-3">
          <div className="p-3 bg-light shadow rounded" style={{ height: "100%" }}>
            <h5>Navegación</h5>
            <ul className="nav flex-column">
              <li className="nav-item">
                <a className="nav-link" href="#">Inicio</a>
              </li>
              <li className="nav-item">
                <a className="nav-link" href="#">Películas Activas</a>
              </li>
              <li className="nav-item">
                <a className="nav-link" href="#">Películas Inactivas</a>
              </li>
              <li className="nav-item">
                <a className="nav-link" href="#">Todas</a>
              </li>
            </ul>
          </div>
        </div>
      </div>
    </div>
  );
};

export default MovieList;
